const briefing = $('AI Agent 1: Briefing Summary1').item.json.output || {};
const persona = $('Ai Agent 2: User Persona\'s1').item.json.output || {};
const tokens = $('Ai Agent3: Design Research & Style Tokens1').item.json.output || {};
const decisions = $input.item.json.output || '(geen designbeslissingen gevonden)';

const keyFeatures = briefing.keyFeatures || [];
const frustrations = persona.frustrations || [];

const md = `# 00 — Project Overview

## Wat is dit project
${briefing.projectGoal || '(niet beschikbaar)'}

## Voor wie
${briefing.targetUsers || '(niet beschikbaar)'}

## Kernfunctionaliteiten
${keyFeatures.map(f => `- ${f}`).join('\n') || '(geen features gevonden)'}

## Primaire gebruiker (persona)
**${persona.name || '(onbekend)'}** — ${persona.role || ''}
