let raw = $input.item.json.output;

function tryParse(str) {
  try { return JSON.parse(str); } catch (e) { return null; }
}

// raw might already be an object if the agent returned clean JSON
let parsed = (typeof raw === 'object' && raw !== null) ? raw : tryParse(raw);

// Handle Fable 5's double-wrapping quirk: {"output": "<json string>"}
if (parsed && typeof parsed === 'object' && typeof parsed.output === 'string' && !parsed.userStories) {
  const inner = tryParse(parsed.output);
  if (inner) parsed = inner;
}

// Fallback: extract the first {...} block from raw text (handles markdown fences etc.)
if ((!parsed || !parsed.userStories) && typeof raw === 'string') {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    const attempt = tryParse(match[0]);
    if (attempt) parsed = attempt;
  }
}

// Final safety net so downstream nodes never crash on a missing field
if (!parsed || typeof parsed !== 'object') {
  parsed = { userStories: [], functionalRequirements: [], missingInfo: ['Could not parse model output - check AI Agent 4 raw output'] };
}
if (!Array.isArray(parsed.userStories)) parsed.userStories = [];
if (!Array.isArray(parsed.functionalRequirements)) parsed.functionalRequirements = [];
if (!Array.isArray(parsed.missingInfo)) parsed.missingInfo = [];

return { json: { output: parsed } };

