const buffer = await this.helpers.getBinaryDataBuffer(0, 'screenshotFile');
const base64 = buffer.toString('base64');
const info = $input.item.binary.screenshotFile;
const fileName = (info.fileName || '').toLowerCase();
const supported = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
let mimeType = info.mimeType;
if (!supported.includes(mimeType)) {
  if (fileName.endsWith('.png')) mimeType = 'image/png';
  else if (fileName.endsWith('.jpg') || fileName.endsWith('.jpeg')) mimeType = 'image/jpeg';
  else if (fileName.endsWith('.gif')) mimeType = 'image/gif';
  else if (fileName.endsWith('.webp')) mimeType = 'image/webp';
  else mimeType = 'image/png';
}
return {
  json: { ...$input.item.json, screenshotBase64: base64, screenshotMimeType: mimeType },
  binary: $input.item.binary
};

const buffer = await this.helpers.getBinaryDataBuffer(0, 'initialDesignFile');
const base64 = buffer.toString('base64');
return {
  json: { ...$input.item.json, designPdfBase64: base64 },
  binary: $input.item.binary
};

const response = $json;
let text = '';
try {
