function safeGet(nodeName, field) {
  try {
    const val = $(nodeName).item.json[field];
    return (val !== undefined && val !== null) ? val : null;
  } catch (e) {
    return null;
  }
}

const changeTranscript = safeGet('Normalize Transcript PDF Text', 'changeTranscript')
  ?? safeGet('Extract Transcript Text', 'changeTranscript')
  ?? '';

const screenshotInterpretation = safeGet('Parse Screenshot Result', 'screenshotInterpretation')
  ?? safeGet('No Screenshot Fallback', 'screenshotInterpretation')
  ?? '';

return {
  json: {
    ...$input.item.json,
    changeTranscript,
    screenshotInterpretation,
    _debugTranscriptLength: changeTranscript.length,
    _debugTranscriptPreview: changeTranscript.slice(0, 150)
  }
};
